('103', 1, 1, 'Classic Suite', 'available', 9000.00, 'Inviting Classic Suite with elegant décor inspired by Kolkata rich cultural heritage. Features warm lighting, premium linens, and a spacious work desk.', 2, '34 sqm', 'Wi-Fi, Smart TV, Mini Bar, Tea/Coffee Maker, Safe, Air Conditioning, Work Desk, Room Service', 'https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?w=800', 'City View', 'King Bed'),
('104', 1, 1, 'Classic Suite', 'available', 8500.00, 'A serene Classic Suite offering peaceful garden views and timeless elegance. Ideal for solo travelers or couples seeking a restful Kolkata escape.', 2, '32 sqm', 'Wi-Fi, Smart TV, Mini Bar, Tea/Coffee Maker, Safe, Air Conditioning, Room Service', 'https://images.unsplash.com/photo-1631049307264-da0ec9d70304?w=800', 'Garden View', 'Twin Beds'),
('105', 1, 1, 'Classic Suite', 'available', 8500.00, 'Tastefully designed Classic Suite with contemporary touches and traditional charm. Features a comfortable seating area and premium bathroom amenities.', 2, '32 sqm', 'Wi-Fi, Smart TV, Mini Bar, Tea/Coffee Maker, Safe, Air Conditioning, Room Service', 'https://images.unsplash.com/photo-1618773928121-c32242e63f39?w=800', 'Courtyard View', 'King Bed');
INSERT INTO rooms (room_number, floor, category_id, suite_category, status, nightly_rate, description, max_occupancy, dimensions, amenities, image_url, view_type, bed_type) VALUES
('201', 2, 2, 'Deluxe Suite', 'available', 12500.00, 'Expansive Deluxe Suite with separate living area, designer furnishings, and panoramic views of the Kolkata city skyline. A perfect blend of modern luxury and Bengali artistic flair.', 3, '45 sqm', 'Wi-Fi, Smart TV, Mini Bar, Nespresso Machine, Safe, Air Conditioning, Work Desk, Bathrobe & Slippers, Premium Toiletries, Room Service', 'https://images.unsplash.com/photo-1591088398332-8a7791972843?w=800', 'City Skyline View', 'King Bed'),
