('203', 2, 2, 'Deluxe Suite', 'available', 13000.00, 'Luxurious Deluxe Suite with an open-plan layout, elegant chandelier lighting, and floor-to-ceiling windows showcasing Kolkata cityscape.', 3, '48 sqm', 'Wi-Fi, Smart TV, Mini Bar, Nespresso Machine, Safe, Air Conditioning, Work Desk, Bathrobe & Slippers, Premium Toiletries, Room Service', 'https://images.unsplash.com/photo-1566665797739-1674de7a421a?w=800', 'City View', 'King Bed + Sofa Bed'),
('204', 2, 2, 'Deluxe Suite', 'available', 12500.00, 'Refined Deluxe Suite with a calming palette of ivory and champagne tones, premium Egyptian cotton bedding, and curated Kolkata-inspired artwork.', 3, '45 sqm', 'Wi-Fi, Smart TV, Mini Bar, Nespresso Machine, Safe, Air Conditioning, Work Desk, Bathrobe & Slippers, Premium Toiletries, Room Service', 'https://images.unsplash.com/photo-1560185893-a55cbc8c57e8?w=800', 'Garden View', 'King Bed'),
('205', 2, 2, 'Deluxe Suite', 'available', 12500.00, 'Graceful Deluxe Suite offering a private balcony, sumptuous seating nook, and views of the hotel manicured landscape. A haven of luxury in Kolkata.', 3, '45 sqm', 'Wi-Fi, Smart TV, Mini Bar, Nespresso Machine, Safe, Air Conditioning, Work Desk, Bathrobe & Slippers, Premium Toiletries, Balcony, Room Service', 'https://images.unsplash.com/photo-1595526114035-0d45ed16cfbf?w=800', 'Garden View', 'King Bed');
INSERT INTO rooms (room_number, floor, category_id, suite_category, status, nightly_rate, description, max_occupancy, dimensions, amenities, image_url, view_type, bed_type) VALUES
