('303', 3, 4, 'Executive Suite', 'available', 18500.00, 'Executive Suite designed for the modern business traveler. Features a dedicated workspace with ergonomic chair, high-speed internet, and access to the Executive Lounge.', 3, '58 sqm', 'Wi-Fi, Smart TV, Mini Bar, Nespresso Machine, Safe, Air Conditioning, Executive Work Desk, Ergonomic Chair, Bathrobe & Slippers, Premium Toiletries, Jacuzzi Tub, Executive Lounge Access, Butler Service, Room Service', 'https://images.unsplash.com/photo-1631049552057-403cdb8f0658?w=800', 'City View', 'King Bed'),
('304', 3, 4, 'Executive Suite', 'available', 18500.00, 'Premier Executive Suite with separate meeting area, premium sound system, and stunning views of the Kolkata luxury district. Ideal for executives and VIPs.', 3, '60 sqm', 'Wi-Fi, Smart TV, Mini Bar, Nespresso Machine, Safe, Air Conditioning, Executive Work Desk, Meeting Area, Bathrobe & Slippers, Premium Toiletries, Jacuzzi Tub, Executive Lounge Access, Butler Service, Room Service', 'https://images.unsplash.com/photo-1594563703937-fdc640497dcd?w=800', 'City Skyline View', 'King Bed'),
('305', 3, 3, 'Premium Suite', 'available', 16500.00, 'A grand Premium Suite featuring opulent décor, a luxurious soaking tub, and curated views of the Royal Avenue gardens. An oasis of indulgence and comfort.', 3, '56 sqm', 'Wi-Fi, Smart TV, Mini Bar, Nespresso Machine, Safe, Air Conditioning, Work Desk, Bathrobe & Slippers, Premium Toiletries, Jacuzzi Tub, Butler Service, Room Service', 'https://images.unsplash.com/photo-1590490359683-658d3d23f972?w=800', 'Garden View', 'King Bed');
INSERT INTO rooms (room_number, floor, category_id, suite_category, status, nightly_rate, description, max_occupancy, dimensions, amenities, image_url, view_type, bed_type) VALUES
('401', 4, 6, 'Presidential Suite', 'available', 45000.00, 'The crown jewel of Regalia Hotel. This magnificent Presidential Suite features a grand living room, private dining hall, study, and panoramic views of Kolkata. Handcrafted Italian marble, Swarovski chandeliers, and a personal butler ensure an unparalleled experience.', 4, '120 sqm', 'Wi-Fi, Smart TV, Full Bar, Nespresso Machine, Safe, Climate Control, Executive Work Desk, Private Dining Room, Bathrobe & Slippers, Hermès Toiletries, Jacuzzi & Steam Shower, 24/7 Butler Service, Private Elevator Access, Limousine Service, Room Service', 'https://images.unsplash.com/photo-1578683010236-d716f9a3f461?w=800&preset=premium', 'Panoramic City View', 'Emperor Bed'),
('402', 4, 6, 'Presidential Suite', 'available', 45000.00, 'An exquisite Presidential Suite offering the ultimate in luxury. Featuring a master bedroom, guest room, private lounge, and wraparound terrace with Kolkata skyline views.', 4, '125 sqm', 'Wi-Fi, Smart TV, Full Bar, Nespresso Machine, Safe, Climate Control, Executive Work Desk, Private Lounge, Bathrobe & Slippers, Hermès Toiletries, Jacuzzi & Steam Shower, 24/7 Butler Service, Private Elevator Access, Limousine Service, Room Service', 'https://images.unsplash.com/photo-1582719508461-900522c89192?w=800&preset=premium', 'Skyline View', 'Emperor Bed'),
('403', 4, 5, 'Royal Suite', 'available', 28000.00, 'The Royal Kolkata Enclave Suite. A majestic retreat featuring regal décor, a private sitting room, and breathtaking views of the city. Every detail reflects the grandeur of Kolkata royal heritage.', 4, '85 sqm', 'Wi-Fi, Smart TV, Premium Bar, Nespresso Machine, Safe, Climate Control, Executive Work Desk, Bathrobe & Slippers, Premium Toiletries, Jacuzzi Tub, 24/7 Butler Service, Private Elevator Access, Room Service', 'https://images.unsplash.com/photo-1611892440504-42a792e24d32?w=800&preset=premium', 'City View', 'Super King Bed'),
('404', 4, 5, 'Royal Suite', 'available', 28000.00, 'A palatial Royal Suite inspired by the architectural splendor of Kolkata. Features ornate moldings, silk draperies, a grand piano, and a private library corner.', 4, '88 sqm', 'Wi-Fi, Smart TV, Premium Bar, Nespresso Machine, Safe, Climate Control, Executive Work Desk, Private Library, Bathrobe & Slippers, Premium Toiletries, Jacuzzi Tub, 24/7 Butler Service, Room Service', 'https://images.unsplash.com/photo-1596394516093-501ba68a0ba6?w=800&preset=premium', 'Garden & City View', 'Super King Bed');
INSERT INTO rooms (room_number, floor, category_id, suite_category, status, nightly_rate, description, max_occupancy, dimensions, amenities, image_url, view_type, bed_type) VALUES
('501', 5, 5, 'Royal Suite', 'available', 32000.00, 'The pinnacle Royal Suite on the top floor offering unobstructed 360-degree views of Kolkata. Features a private rooftop terrace, infinity plunge pool, and dedicated concierge service.', 4, '95 sqm', 'Wi-Fi, Smart TV, Full Bar, Nespresso Machine, Safe, Climate Control, Executive Work Desk, Private Terrace, Plunge Pool, Bathrobe & Slippers, Hermès Toiletries, Jacuzzi & Steam Shower, 24/7 Butler & Concierge, Private Elevator, Limousine Service, Room Service', 'https://images.unsplash.com/photo-1591088398332-8a7791972843?w=800&preset=premium', '360° Panoramic View', 'Emperor Bed'),
('502', 5, 5, 'Royal Suite', 'available', 30000.00, 'An extraordinary Royal Suite featuring floor-to-ceiling windows, a private art gallery, and Kolkata finest luxury appointments. A residence befitting royalty.', 4, '92 sqm', 'Wi-Fi, Smart TV, Full Bar, Nespresso Machine, Safe, Climate Control, Executive Work Desk, Private Art Gallery, Bathrobe & Slippers, Hermès Toiletries, Jacuzzi & Steam Shower, 24/7 Butler Service, Private Elevator, Room Service', 'https://images.unsplash.com/photo-1578683010236-d716f9a3f461?w=800&preset=premium', 'Panoramic City View', 'Emperor Bed'),
